  const issued = issueInvoice(invResult.value, []);
  assert.equal(issued.ok, true);

  const r = vatSummary([issued.value]);
  assert.equal(r.ok, true);

  // DEV-HOUR is 5000 cents per hour
  // 10 * 5000 = 50000, minus 10% discount = 50000 - 5000 = 45000
  // VAT at 21% on 45000 = 9450
  assert.equal(r.value[0].rate, 21);
  assert.equal(r.value[0].base, 45000);
  assert.equal(r.value[0].vat, 9450);
});

