  const inv1Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5, discountPercent: 0 },
      { sku: 'BUNDLE', qty: 2, discountPercent: 0 },
    ],
  });
  const inv2Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 3, discountPercent: 0 }],
  });

  assert.equal(inv1Result.ok, true);
  assert.equal(inv2Result.ok, true);

  const issued1 = issueInvoice(inv1Result.value, []);
  const issued2 = issueInvoice(inv2Result.value, ['INV-2026-0001']);

  const r = vatSummary([issued1.value, issued2.value]);
  assert.equal(r.ok, true);

  // Should have entries for rates: 21 (DEV-HOUR), 0 (BUNDLE), 9 (LOGO-PACK)
  assert(r.value.length >= 2);

  // Check sorted descending
  for (let i = 0; i < r.value.length - 1; i++) {
    assert(r.value[i].rate >= r.value[i + 1].rate);
  }
});

test('vatSummary includes fields: rate, base, vat', () => {
  const invResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5, discountPercent: 0 }],
  });
  assert.equal(invResult.ok, true);

