  assert.equal(issued.ok, true);

  const r = vatSummary([issued.value]);
  assert.equal(r.ok, true);
  assert.equal(r.value.length, 1);

  const entry = r.value[0];
  assert(typeof entry.rate === 'number');
  assert(typeof entry.base === 'number');

