  const r = overdueInvoices([issued.value], '2026-10-22');
  assert.equal(r.ok, true);
  assert.equal(r.value[0].daysOverdue, 7);
});

test('overdueInvoices returns due amount for each invoice', () => {
  const invResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  assert.equal(invResult.ok, true);

  const issued = issueInvoice(invResult.value, []);
  assert.equal(issued.ok, true);

  const r = overdueInvoices([issued.value], '2026-11-07');
  assert.equal(r.ok, true);
  assert.equal(r.value[0].due, balanceDue(issued.value));
});

test('overdueInvoices sorts by daysOverdue descending', () => {
  const inv1Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  const inv2Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-05',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  const inv3Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-10',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET14',
  });

  assert.equal(inv1Result.ok, true);
  assert.equal(inv2Result.ok, true);
  assert.equal(inv3Result.ok, true);

  const issued1 = issueInvoice(inv1Result.value, []);
  const issued2 = issueInvoice(inv2Result.value, ['INV-2026-0001']);
  const issued3 = issueInvoice(inv3Result.value, ['INV-2026-0001', 'INV-2026-0002']);

  // dueDate: inv1=2026-10-15, inv2=2026-10-19, inv3=2026-10-24
  const r = overdueInvoices([issued1.value, issued2.value, issued3.value], '2026-10-30');
  assert.equal(r.ok, true);
  assert.equal(r.value.length, 3);

  // Should be sorted: most overdue first (inv1 at 15 days, inv2 at 11 days, inv3 at 6 days)
  assert.equal(r.value[0].daysOverdue, 15);
  assert.equal(r.value[1].daysOverdue, 11);
  assert.equal(r.value[2].daysOverdue, 6);
});

test('overdueInvoices returns empty for no overdue invoices', () => {
  const invResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
    terms: 'NET14',
  });
  assert.equal(invResult.ok, true);

  const issued = issueInvoice(invResult.value, []);
  assert.equal(issued.ok, true);

  const r = overdueInvoices([issued.value], '2026-10-14');
  assert.equal(r.ok, true);
  assert.equal(r.value.length, 0);
});

test('overdueInvoices returns DATE_INVALID for invalid asOf', () => {
  const r = overdueInvoices([], 'invalid-date');
  assert.deepEqual(r, { ok: false, error: 'DATE_INVALID' });
});

test('overdueInvoices with mix of overdue and current invoices', () => {
  const inv1Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
